    internalLinks: [{"title":"Kassensystem","href":"/de/produkte/pakete/kassensystem"},{"title":"Restaurant","href":"/de/loesungen/restaurant"},{"title":"Cafe baeckerei","href":"/de/loesungen/cafe-baeckerei"}],
